    import json
    from collections import deque

    class Node:
        def __init__(self, val=0, neighbors=None):
            self.val = val
            self.neighbors = neighbors or []

    def build_graph(adj_list):
        if not adj_list:
            return None
        nodes = {i + 1: Node(i + 1) for i in range(len(adj_list))}
        for i, neighbors in enumerate(adj_list):
            nodes[i + 1].neighbors = [nodes[n] for n in neighbors]
        return nodes[1]

    def serialize_graph(node):
        if not node:
            return []
        seen = {node.val: node}
        q = deque([node])
        while q:
            curr = q.popleft()
            for nxt in curr.neighbors:
                if nxt.val not in seen:
                    seen[nxt.val] = nxt
                    q.append(nxt)
        return [[n.val for n in seen[i].neighbors] for i in range(1, len(seen) + 1)]

